import type {
	AgentMessage,
	BashExecutionMessage,
	BranchSummaryEntry,
	CompactionEntry,
	CustomEntry,
	CustomMessage,
	CustomMessageEntry,
	LabelEntry,
	ModelChangeEntry,
	SessionContext,
	SessionTreeEntry as SessionEntry,
	SessionTreeEntryBase as SessionEntryBase,
	SessionInfoEntry,
	MessageEntry as SessionMessageEntry,
	ThinkingLevelChangeEntry,
} from "@kolisachint/hoocode-agent-core";
import { buildSessionContext as buildContextFromPath } from "@kolisachint/hoocode-agent-core";
import type { ImageContent, Message, TextContent } from "@kolisachint/hoocode-ai";
import { randomUUID } from "crypto";
import {
	appendFileSync,
	closeSync,
	existsSync,
	mkdirSync,
	openSync,
	readdirSync,
	readFileSync,
	readSync,
	statSync,
	writeFileSync,
} from "fs";
import { readdir, readFile, stat } from "fs/promises";
import { join, resolve } from "path";
import { v7 as uuidv7 } from "uuid";
import { getAgentDir as getDefaultAgentDir, getSessionsDir } from "../config.js";

// Session entry types are shared with the agent harness; re-exported here under
// their historical coding-agent names.
export type {
	BranchSummaryEntry,
	CompactionEntry,
	CustomEntry,
	CustomMessageEntry,
	LabelEntry,
	MessageEntry as SessionMessageEntry,
	ModelChangeEntry,
	SessionContext,
	SessionInfoEntry,
	SessionTreeEntry as SessionEntry,
	SessionTreeEntryBase as SessionEntryBase,
	ThinkingLevelChangeEntry,
} from "@kolisachint/hoocode-agent-core";

export const CURRENT_SESSION_VERSION = 3;

export interface SessionHeader {
	type: "session";
	version?: number; // v1 sessions don't have this
	id: string;
	timestamp: string;
	cwd: string;
	parentSession?: string;
}

export interface NewSessionOptions {
	id?: string;
	parentSession?: string;
}

/** Raw file entry (includes header) */
export type FileEntry = SessionHeader | SessionEntry;

/** Tree node for getTree() - defensive copy of session structure */
export interface SessionTreeNode {
	entry: SessionEntry;
	children: SessionTreeNode[];
	/** Resolved label for this entry, if any */
	label?: string;
	/** Timestamp of the latest label change for this entry, if any */
	labelTimestamp?: string;
}

export interface SessionInfo {
	path: string;
	id: string;
	/** Working directory where the session was started. Empty string for old sessions. */
	cwd: string;
	/** User-defined display name from session_info entries. */
	name?: string;
	/** Path to the parent session (if this session was forked). */
	parentSessionPath?: string;
	created: Date;
	modified: Date;
	messageCount: number;
	firstMessage: string;
	allMessagesText: string;
}

